x-codeSamples.source:
$url = "https://console.kamatera.com/service/docs"
$headers = @{
  "Content-Type" = "application/json"
}

try {
  $result = Invoke-WebRequest -Uri $url -Method GET -Headers $headers
  Write-Output $result.Content 
}
catch {
  $result = $_.Exception.Response.GetResponseStream()
  $reader = New-Object System.IO.StreamReader($result)
  $reader.BaseStream.Position = 0
  $reader.DiscardBufferedData()
  $responseBody = $reader.ReadToEnd();
  Write-Output $responseBody
}

fetch('https://console.kamatera.com/service/docs', {
    method: 'GET',
    headers: {
      "Content-Type": "application/json"
    },
}).then(response => response.json())
  .then(data => console.log(data))
  .catch(err => console.log(err));

const config = {
  url: 'https://console.kamatera.com/service/docs',
  method: 'get',
  headers: {
      "Content-Type": "application/json"
    },
}
axios.request(config).then(({data}) => console.log(data))
  .catch(err => console.log(err.response.data));

using System;
using System.Net.Http;
var client = new HttpClient();
var request = new HttpRequestMessage(HttpMethod.Get, "https://console.kamatera.com/service/docs");

var response = await client.SendAsync(request);
response.EnsureSuccessStatusCode();
Console.WriteLine(await response.Content.ReadAsStringAsync());

package main

import (
  "fmt"
  "net/http"
  "io/ioutil"
)

func main() {

  url := "https://console.kamatera.com/service/docs"
  method := "GET"
  client := &http.Client {
  }

  req, err := http.NewRequest(method, url, nil)
  if err != nil {
    fmt.Println(err)
    return
  }
  req.Header.Add("Content-Type", "application/json");

  res, err := client.Do(req)
  if err != nil {
    fmt.Println(err)
    return
  }

  defer res.Body.Close()
  body, err := ioutil.ReadAll(res.Body)
  if err != nil {
    fmt.Println(err)
    return
  }

  fmt.Println(string(body))
}

